import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
const read=p=>JSON.parse(fs.readFileSync(new URL('../'+p,import.meta.url)));
test('September 29 records three actual outputs and no independent acceptance',()=>{const b=read('assets/citizen-work.json'),d=b.deliveries.filter(x=>x.executionId==='daily-20260929-root');assert.deepEqual(d.map(x=>x.citizenId).sort(),['cynosure','nullroute','vox']);for(const x of d)assert.equal(x.review,null);for(const id of ['cynosure','nullroute','vox']){const n=read(`research/2026-09-29/${id}.json`);for(const l of ['zh','en','ko'])for(const k of ['title','lead','limitation','next'])assert.ok(n[k][l]);for(const a of n.attachments)assert.ok(fs.existsSync(new URL('../'+a.path,import.meta.url)));}});
test('source failures remain failures and frozen forecasts are unresolved',()=>{const s=read('research/2026-09-29/source-checks.json');assert.equal(s.sources.filter(x=>x.status==='access_failed'&&x.httpStatus===403).length,2);const f=read('research/2026-09-25/cynosure-forecasts.json');assert.deepEqual(f.cards.map(c=>c.probability),[.65,.55]);assert.ok(f.cards.every(c=>c.outcome===null&&c.brier===null));});
